function dungeonBoss(){const r=DUNGEON.rooms[DUNGEON.bossRoom],x=r.x+r.w/2,y=r.y+r.h*.43;return{id:'warden',x,y,homeX:x,homeY:y,dungeonRoom:DUNGEON.bossRoom,rank:3,boss:true,bossIndex:0,name:'Kara Taş Gardiyanı',hp:1100,max:1100,phase:1,dead:0,hit:0,bossCooldown:2}}
function storeDungeonRun(){if(!dungeonRun)return;p.dungeonRun={version:DUNGEON.version,complete:dungeonRun.complete,rewarded:dungeonRun.rewarded,features:dungeonRun.features,enemies:enemies.filter(e=>e.id).map(e=>({id:e.id,x:e.x,y:e.y,hp:e.hp,dead:!!e.dead}))}}
