 for(const e of enemies){const s=legacyCleared.has(e.dungeonRoom)?{dead:true}:snapshots.get(e.id);if(s){e.dead=s.dead?1:0;e.hp=e.dead?0:Math.max(1,Math.min(e.max,Number(s.hp)||e.max));const r=DUNGEON.rooms[e.dungeonRoom];if(Number.isFinite(s.x)&&Number.isFinite(s.y)&&insideDungeonRect(s.x,s.y,r,45)){e.x=s.x;e.y=s.y}}}
