const enterBeforeDungeon=enterForest;enterForest=function(){enterBeforeDungeon();loadDungeonRun(!!p.dungeonRun?.complete);p.x=DUNGEON.entry.x;p.y=DUNGEON.entry.y;spinAction=null;keys={};p.destination=null;save();toast('Kara Taş Mahzeni · Odaları temizle, mühürleri aç.');updateDungeonReadout()};
