for(const q of CONTRACTS){if(q.id==='firstBoss'){q.name='Mahzenin gardiyanı';q.description='Kara Taş Gardiyanı’nı yen.'}if(q.id==='explorer'){q.name='Altı mühür';q.description='Bir denemede altı büyük savaş odasını temizle.';q.done=()=>(p.dungeonBestRooms||0)>=DUNGEON.combatCount}if(q.id==='allBosses'){q.name='Mahzen ustası';q.description='Kara Taş Mahzeni’ni üç kez tamamla.';q.done=()=>(p.dungeonClears||0)>=3}}
const destinationBeforeDungeon=destinationFor;destinationFor=function(id){if(id==='exit'&&p.area==='forest')return{...DUNGEON.entry,area:'forest',name:'Köye çekil'};if(id?.startsWith('boss:'))return{x:DUNGEON.rooms[DUNGEON.bossRoom].x+550,y:DUNGEON.rooms[DUNGEON.bossRoom].y+600,area:'forest',name:'Kara Taş Gardiyanı'};return destinationBeforeDungeon(id)};
